# ---------------------------------------------------------------------------
# Ollama helpers
# ---------------------------------------------------------------------------

def _find_ollama_exe() -> Optional[str]:
    import shutil
    found = shutil.which("ollama") or shutil.which("ollama.exe")
    if found:
        return found
    for root in Trio_OLLAMA_SEARCH_DIRS:
        if not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            depth = dirpath.replace(root, "").count(os.sep)
            if depth > 3:
                dirnames.clear()
                continue
            for fname in filenames:
                if fname.lower() in ("ollama.exe", "ollama"):
                    return os.path.join(dirpath, fname)
    return None

def _ping(url: str) -> bool:
    try:
        urllib.request.urlopen(f"{url}/api/tags", timeout=3)
        return True
    except Exception:
        return False

_Trio_ollama_proc: Optional[subprocess.Popen] = None  # only set if WE started ollama

def Trio_ensure_ollama_running() -> bool:
    global _Trio_ollama_proc
    if _ping(Trio_OLLAMA_URL):
        return True  # already running (not ours) -> leave it alone on exit
    exe = _find_ollama_exe()
    if not exe:
        return False
    _Trio_ollama_proc = subprocess.Popen(
        [exe, "serve"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        creationflags=subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0,
    )
    for _ in range(15):
        time.sleep(1)
        if _ping(Trio_OLLAMA_URL):
            return True
    return False

def Trio_stop_ollama():
    """Terminate the Ollama server, but only if this app started it."""
    global _Trio_ollama_proc
    if _Trio_ollama_proc is None:
        return
    try:
        if sys.platform == "win32":
            subprocess.run(
                ["taskkill", "/F", "/T", "/PID", str(_Trio_ollama_proc.pid)],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        else:
            _Trio_ollama_proc.terminate()
        try:
            _Trio_ollama_proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            _Trio_ollama_proc.kill()
    except Exception:
        pass
    finally:
        _Trio_ollama_proc = None

def Trio_list_models() -> List[str]:
    try:
        with urllib.request.urlopen(f"{Trio_OLLAMA_URL}/api/tags", timeout=5) as r:
            return [m["name"] for m in json.loads(r.read()).get("models", [])]
    except Exception:
        return []

def Trio_pick_model(preferred: Optional[str] = None) -> Optional[str]:
    available = Trio_list_models()
    if not available:
        return None
    if preferred:
        for name in available:
            if preferred in name or name.startswith(preferred):
                return name
    return available[0]

# ---------------------------------------------------------------------------
# Bot config — stateless, no per-bot history deque
# ---------------------------------------------------------------------------

@dataclass
class Trio_BotConfig:
    name: str
    system_prompt: str
    model: str
    max_tokens: int
    temperature: float
    stream: bool

# ---------------------------------------------------------------------------
# HTTP
# ---------------------------------------------------------------------------

class Trio_OllamaError(Exception):
    pass

def _token_from(obj: dict) -> str:
    msg = obj.get("message", {})
    return (msg.get("content") or obj.get("response") or msg.get("thinking") or "")

def _stream_req(payload: dict, callback: Callable[[str], None], timeout: int = 120) -> str:
    payload = {**payload, "stream": True}
    data = json.dumps(payload).encode()
    req = urllib.request.Request(
        f"{Trio_OLLAMA_URL}/api/chat",
        data=data,
        headers={"Content-Type": "application/json"},
    )
    chunks: List[str] = []
    with urllib.request.urlopen(req, timeout=timeout) as r:
        for raw in r:
            line = raw.strip()
            if not line:
                continue
            obj = json.loads(line)
            token = _token_from(obj)
            if token:
                callback(token)
                chunks.append(token)
            if obj.get("done"):
                break
    return "".join(chunks)

def _post_req(payload: dict, timeout: int = 120) -> dict:
    data = json.dumps(payload).encode()
    req = urllib.request.Request(
        f"{Trio_OLLAMA_URL}/api/chat",
        data=data,
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode())

def Trio_chat_bot(
    bot: Trio_BotConfig,
    shared_log: List[dict],
    max_history: int,
    extra_context: str = "",
    stream_callback: Optional[Callable[[str], None]] = None,
) -> str:
    """Legacy single-bot call — kept for compatibility but not used in Trio_main flow."""
    recent = shared_log[-(max_history * 3):]
    transcript = "\n".join(f"{e['role']}: {e['text']}" for e in recent)
    prompt = f"[Group chat transcript]\n{transcript}"
    if extra_context:
        prompt += f"\n\n{extra_context}"
    prompt += f"\n\nRespond as {bot.name} now. Follow your response format exactly."
    messages = [
        {"role": "system", "content": bot.system_prompt},
        {"role": "user",   "content": prompt},
    ]
    payload = {
        "model":    bot.model,
        "messages": messages,
        "options":  {"temperature": bot.temperature, "num_predict": bot.max_tokens},
        "stream":   False,
    }
    if bot.stream and stream_callback:
        text = _stream_req(payload, callback=stream_callback)
    else:
        result = _post_req(payload)
        text = _token_from(result).strip()
    if not text:
        text = f"{bot.name} is here."
    return _normalize_reply(text)


def Trio_chat_both_bots(
    model: str,
    temperature: float,
    max_tokens: int,
    shared_log: List[dict],
    max_history: int,
    first_role_cb: Optional[Callable[[str], None]] = None,
    second_role_cb: Optional[Callable[[str], None]] = None,
    on_switch: Optional[Callable[[], None]] = None,
    yuhee_first: bool = True,
) -> tuple:
    """
    Sequential streaming — first speaker streams fully, then second speaker.
    first_role_cb gets whoever speaks first; second_role_cb gets whoever speaks second.
    yuhee_first=True means Yuhee goes first, False means Miku goes first.
    Returns (first_reply, second_reply) as normalized 2-line strings.
    """
    recent = shared_log[-(max_history * 3):]
    transcript = "\n".join(f"{e['role']}: {e['text']}" for e in recent)

    yuhee_prompt = (
        f"[Group chat transcript]\n{transcript}\n\n"
        "Respond as Yuhee now. Exactly 2 lines. No labels. Follow your response format exactly."
    )
    miku_prompt = (
        f"[Group chat transcript]\n{transcript}\n\n"
        "Respond as Miku now. Exactly 2 lines. No labels. Follow your response format exactly."
    )

    results: dict = {}
    errors:  dict = {}

    def _make_payload(system_prompt: str, prompt: str) -> dict:
        return {
            "model":    model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user",   "content": prompt},
            ],
            "think":    False,
            "options":  {
                "temperature":    temperature,
                "num_predict":    max_tokens,
                "num_ctx":        4096,
                "num_thread":     8,
                "repeat_penalty": 1.1,
            },
            "stream": True,
        }

    def _stream_into(key: str, system_prompt: str, prompt: str, callback):
        try:
            payload = _make_payload(system_prompt, prompt)
            data    = json.dumps(payload).encode()
            req     = urllib.request.Request(
                f"{Trio_OLLAMA_URL}/api/chat",
                data=data,
                headers={"Content-Type": "application/json"},
            )
            chunks: List[str] = []
            with urllib.request.urlopen(req, timeout=60) as r:
                for raw_line in r:
                    raw_line = raw_line.strip()
                    if not raw_line:
                        continue
                    obj   = json.loads(raw_line)
                    token = _token_from(obj)
                    if token:
                        chunks.append(token)
                        if callback:
                            for ch in token:
                                callback(ch)
                    if obj.get("done"):
                        break
            results[key] = "".join(chunks).strip()
        except Exception as exc:
            errors[key]  = str(exc)
            results[key] = f"[{key} error: {exc}]"

    if yuhee_first:
        first_key,  second_key    = "yuhee", "miku"
        first_sys,  second_sys    = Trio_YUHEE_SYSTEM, Trio_MIKU_SYSTEM
        first_prompt, second_prompt = yuhee_prompt, miku_prompt
    else:
        first_key,  second_key    = "miku", "yuhee"
        first_sys,  second_sys    = Trio_MIKU_SYSTEM, Trio_YUHEE_SYSTEM
        first_prompt, second_prompt = miku_prompt, yuhee_prompt

    t_first  = threading.Thread(
        target=_stream_into,
        args=(first_key,  first_sys,  first_prompt,  first_role_cb),
        daemon=True,
    )

    t_first.start()
    t_first.join()          # wait for the first reply to fully finish before starting the second —
                             # firing both concurrently caused GPU-side decode corruption (GGGG output)
                             # on the Intel Arc/oneAPI backend.
    if on_switch:
        on_switch()

    t_second = threading.Thread(
        target=_stream_into,
        args=(second_key, second_sys, second_prompt, second_role_cb),
        daemon=True,
    )
    t_second.start()
    t_second.join()

    first_raw  = results.get(first_key,  "")
    second_raw = results.get(second_key, "")
    return _normalize_reply(first_raw), _normalize_reply(second_raw)

# ---------------------------------------------------------------------------
# Persistent History
# ---------------------------------------------------------------------------

Trio_HISTORY_FILE = os.path.join(os.path.expanduser("~"), ".trio_chat_history.json")

def Trio_load_history() -> List[dict]:
    try:
        if os.path.exists(Trio_HISTORY_FILE):
            with open(Trio_HISTORY_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return []

def Trio_save_history(records: List[dict]) -> None:
    try:
        with open(Trio_HISTORY_FILE, "w", encoding="utf-8") as f:
            json.dump(records, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

# ---------------------------------------------------------------------------
# Reply normalizer & parser
# ---------------------------------------------------------------------------

def _normalize_reply(text: str) -> str:
    import re
    text = text.strip()
    if re.match(r"^\*[^*\n]+\*\s*\n", text):
        return text
    m = re.search(r"\*([^*]+)\*", text)
    if m:
        imagery = m.group(1).strip()
        rest = (text[:m.start()] + text[m.end():]).strip()
        rest = re.sub(r"\*", "", rest).strip('"\'\u201c\u201d\u2018\u2019').strip()
        if not rest:
            rest = imagery
        return f"*{imagery}*\n{rest}"
    split_idx = text.find(". ")
    if split_idx != -1 and split_idx < len(text) - 2:
        imagery = text[:split_idx + 1].strip()
        rest    = text[split_idx + 2:].strip().strip('"\'\u201c\u201d\u2018\u2019')
        return f"*{imagery}*\n{rest}"
    return text

def _split_response(text: str):
    import re
    text = text.strip()
    lines = [l.strip() for l in text.split("\n") if l.strip()]
    imagery = ""
    dialogue_parts = []
    for line in lines:
        if not imagery:
            m = re.match(r"^\*(.+?)\*\s*$", line)
            if m:
                imagery = m.group(1).strip()
                continue
            m2 = re.match(r"^\*([^*]+)$", line)
            if m2:
                inner = m2.group(1).rstrip("*").strip()
                if inner:
                    imagery = inner
                    continue
            m3 = re.search(r"\*([^*]+)\*", line)
            if m3:
                imagery = m3.group(1).strip()
                leftover = (line[:m3.start()] + line[m3.end():]).strip()
                leftover = re.sub(r"\*", "", leftover).strip('"\'\u201c\u201d\u2018\u2019').strip()
                if leftover:
                    dialogue_parts.append(leftover)
                continue
        clean = re.sub(r"\*([^*]+)\*", r"\1", line)
        clean = re.sub(r"\*", "", clean).strip('"\'\u201c\u201d\u2018\u2019').strip()
        if clean:
            dialogue_parts.append(clean)
    dialogue = " ".join(dialogue_parts)
    return imagery, dialogue

